def definition(direction):
 box=CROPS[direction];x,y=box[:2]
 def local(p):return (p[0]-x,p[1]-y)
 legs=[{'polygon':[local(p) for p in poly],'hip':local(hip),'knee':local(knee),'ankle':local(ankle)} for poly,hip,knee,ankle in LEGS[direction]]
 poly,shoulder,hand,tip=ARM[direction]
 pelvis=(sum(l['hip'][0] for l in legs)/2,sum(l['hip'][1] for l in legs)/2)
 sole=(pelvis[0],sum(l['ankle'][1] for l in legs)/2)
 return {'source':SOURCE,'bounds':box,'legs':legs,'arm':{'polygon':[local(p) for p in poly],'shoulder':local(shoulder),'hand':local(hand),'tip':local(tip)},'pelvis':pelvis,'sole':sole}
